import { Interactive, Sequence, interpolate, interpolateColors, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";
import { forwardRef, useImperativeHandle, useRef, type ComponentProps } from "react";

interface InlineHighlightProps {
  before: string;
  highlight: string;
  after?: string;
  baseColor?: string;
  highlightColor?: string;
  fontSize?: number;
  fontWeight?: number;
  speed?: number;
  className?: string;
}

function InlineHighlightBase({
  before,
  highlight,
  after = "",
  baseColor = "#171717",
  highlightColor = "#ff5e3a",
  fontSize = 48,
  fontWeight = 600,
  speed = 1,
  className,
}: InlineHighlightProps) {
  const frame = useCurrentFrame() * speed;
  const { durationInFrames } = useVideoConfig();

  const progress = interpolate(
    frame,
    [durationInFrames * 0.2, durationInFrames * 0.7],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" },
  );

  const color = interpolateColors(
    progress,
    [0, 1],
    [baseColor, highlightColor],
  );

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        background: "white",
      }}
    >
      <span
        className={className}
        style={{
          fontSize,
          fontWeight,
          color: baseColor,
          letterSpacing: "-0.03em",
          fontFamily:
            "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif",
        }}
      >
        {before}
        <span style={{ color }}>{highlight}</span>
        {after}
      </span>
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  before: {
    type: "text-content",
    default: "Ship faster with ",
    description: "Before",
  },
  highlight: {
    type: "text-content",
    default: "remocn",
    description: "Highlight",
  },
  after: {
    type: "text-content",
    default: ".",
    description: "After",
  },
  baseColor: {
    type: "color",
    default: "#171717",
    description: "Base color",
  },
  highlightColor: {
    type: "color",
    default: "#ff5e3a",
    description: "Highlight color",
  },
  fontSize: {
    type: "number",
    min: 12,
    max: 160,
    step: 1,
    default: 72,
    description: "Font size",
    hiddenFromList: false,
  },
  fontWeight: {
    type: "enum",
    default: "600",
    variants: {
      "400": {},
      "500": {},
      "600": {},
      "700": {},
    },
    description: "Font weight",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["before","highlight","after","baseColor","highlightColor","fontSize","fontWeight","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  before: "Ship faster with ",
  highlight: "remocn",
  after: ".",
  baseColor: "#171717",
  highlightColor: "#ff5e3a",
  fontSize: 72,
  fontWeight: "600",
  speed: 1,
};

type InlineHighlightElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof InlineHighlightBase>;

const InlineHighlightInner = forwardRef<
  HTMLDivElement,
  InlineHighlightElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<InlineHighlight>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <InlineHighlightBase
          {...(componentProps as unknown as ComponentProps<typeof InlineHighlightBase>)}
        />
      </div>
    </Sequence>
  );
});

export const InlineHighlight = Interactive.withSchema({
  Component: InlineHighlightInner,
  componentName: "<InlineHighlight>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
